SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "李存瑰", "aliases": ["李瓌", "李瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李存瑰，供奉官、赴西川赐诏者。", "biography": null, "status": "draft", "id": "a91449a7-a285-52aa-9c4a-0bf81e533f51"}, {"name": "孟知祥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：孟知祥。", "biography": null, "status": "draft", "id": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"name": "马希声", "aliases": ["馬希聲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希声，武安节度副使判长沙府、获委知政总军者。", "biography": null, "status": "draft", "id": "5dca3ac0-5512-58ab-a330-ff34cb75ede8"}, {"name": "袁诠", "aliases": ["袁詮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：袁诠，六军使、领楚水军者。", "biography": null, "status": "draft", "id": "7d2cfb56-e9ac-5d69-80a4-c6e4af7c4d87"}, {"name": "潘约", "aliases": ["潘約"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：潘约，同迎立者。", "biography": null, "status": "draft", "id": "a88eee34-2d64-58b2-a2e1-8511bd653f0c"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "琼华长公主", "aliases": ["瓊華長公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：琼华长公主，孟妻、被迎者。", "biography": null, "status": "draft", "id": "47a28e4d-5849-5319-a919-e8b8abb93e41"}, {"name": "李从珂", "aliases": [], "era": "五代十国", "birth_year": n