": "辛卯马希声卒。", "phases": [], "location_name": "湖南，卒地未独载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "75384663-328b-51b3-ab6f-f0ef64df1108"}, {"title": "袁诠、潘约等迎朗州的马希范而立之", "start_year": 932, "end_year": 932, "time_original": "932年七月马希声卒后；迎立具体日未独载", "dynasty": "五代十国", "description": "袁诠、潘约等迎朗州的马希范而立之。", "phases": [], "location_name": "朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "adb56002-765c-54e7-92e0-83e615846566"}, {"title": "乙未孟知祥遣李存瑰还，表谢罪并告福庆公主之丧", "start_year": 932, "end_year": 932, "time_original": "932年七月乙未遣还；到京及奏闻确日未独载", "dynasty": "五代十国", "description": "乙未孟知祥遣李存瑰还，表谢罪并告福庆公主之丧。", "phases": [], "location_name": "成都至后唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ff0cfde4-dad9-5a8b-bc8f-2f20cde4a7f0"}, {"title": "史书述孟知祥自此复称藩，但愈加骄倨", "start_year": null, "end_year": null, "time_original": "遣使谢罪后持续姿态；具体起止未独年", "dynasty": "五代十国", "description": "史书述孟知祥自此复称藩，但愈加骄倨。", "phases": [], "location_name": "西川与后唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4b93d8f4-98be-5c1b-8853-4996d2c45ea7"}, {"title": "庚子李从珂由西京留守出任凤翔节度使", "start_year": 932, "end_year": 932, "time_original": "932年七月庚子", "dynasty": "五代十国", "description": "庚子李从珂由西京留守出任凤翔节度使。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "854aa3f0-a4e7-53c0-be94-4ba2e3e24637"}, {"title": "朝廷废武兴军，复以凤、兴、文三州隶山南西道", "start_year": 932, "end_year": 932, "time_original": "932年七月本段；确日未独